 "content": "from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 8 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            colors = {grid[y][x] for y, x in cells if grid[y][x] != 0}
            if len(colors) != 1:
                continue
            y0, y1 = min(y for y, x in cells), max(y for y, x in cells)
            x0, x1 = min(x for y, x in cells), max(x for y, x in cells)
            colored = [(y, x) for y, x in cells if grid[y][x] != 0]
            py0, py1 = min(y for y, x in colored), max(y for y, x in colored)
            px0, px1 = min(x for y, x in colored), max(x for y, x in colored)
            th, tw = py1-py0+1, px1-px0+1
            tile = [ [grid[py0+i][px0+j] for j in range(tw)] for i in range(th) ]
            for y, x in cells:
                out[y][x] = tile[(y-y0) % th][(x-x0) % tw]
    return out
